CREATE TABLE products(id INTEGER PRIMARY KEY,name TEXT NOT NULL,normalized_name TEXT NOT NULL,brand TEXT,sku TEXT UNIQUE,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE customers(id INTEGER PRIMARY KEY,name TEXT NOT NULL,normalized_name TEXT NOT NULL,phone TEXT,address TEXT,opening_balance NUMERIC NOT NULL DEFAULT 0);
CREATE TABLE suppliers(id INTEGER PRIMARY KEY,name TEXT NOT NULL,normalized_name TEXT NOT NULL,phone TEXT,address TEXT,opening_balance NUMERIC NOT NULL DEFAULT 0);
CREATE TABLE stock_movements(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,occurred_at TEXT NOT NULL,quantity NUMERIC NOT NULL,direction TEXT NOT NULL,reference TEXT,source_file TEXT,source_sheet TEXT,source_row INTEGER,notes TEXT,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE sales(id INTEGER PRIMARY KEY,invoice_no TEXT UNIQUE NOT NULL,sale_date TEXT NOT NULL,customer_id INTEGER,total NUMERIC NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'posted',FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE sale_items(id INTEGER PRIMARY KEY,sale_id INTEGER NOT NULL,product_id INTEGER NOT NULL,quantity NUMERIC NOT NULL,unit_price NUMERIC NOT NULL,cost_of_goods NUMERIC NOT NULL DEFAULT 0,FOREIGN KEY(sale_id) REFERENCES sales(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE purchases(id INTEGER PRIMARY KEY,invoice_no TEXT UNIQUE,purchase_date TEXT NOT NULL,supplier_id INTEGER,total NUMERIC NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'posted',FOREIGN KEY(supplier_id) REFERENCES suppliers(id));
CREATE TABLE purchase_items(id INTEGER PRIMARY KEY,purchase_id INTEGER NOT NULL,product_id INTEGER NOT NULL,quantity NUMERIC NOT NULL,unit_cost NUMERIC NOT NULL,FOREIGN KEY(purchase_id) REFERENCES purchases(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE customer_ledger(id INTEGER PRIMARY KEY,customer_id INTEGER NOT NULL,occurred_at TEXT NOT NULL,debit NUMERIC NOT NULL DEFAULT 0,credit NUMERIC NOT NULL DEFAULT 0,reference TEXT,source_file TEXT,source_sheet TEXT,source_row INTEGER,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE supplier_ledger(id INTEGER PRIMARY KEY,supplier_id INTEGER NOT NULL,occurred_at TEXT NOT NULL,debit NUMERIC NOT NULL DEFAULT 0,credit NUMERIC NOT NULL DEFAULT 0,reference TEXT,source_file TEXT,source_sheet TEXT,source_row INTEGER,FOREIGN KEY(supplier_id) REFERENCES suppliers(id));
CREATE TABLE payments(id INTEGER PRIMARY KEY,occurred_at TEXT NOT NULL,party_type TEXT NOT NULL,party_id INTEGER,amount NUMERIC NOT NULL,method TEXT,reference TEXT,status TEXT NOT NULL DEFAULT 'posted');
CREATE TABLE expenses(id INTEGER PRIMARY KEY,occurred_at TEXT NOT NULL,category TEXT NOT NULL,amount NUMERIC NOT NULL,description TEXT,status TEXT NOT NULL DEFAULT 'posted');
CREATE TABLE audit_log(id INTEGER PRIMARY KEY,occurred_at TEXT NOT NULL,user_id INTEGER,action TEXT NOT NULL,entity_type TEXT,entity_id INTEGER,details TEXT);
CREATE TABLE migration_rows(id INTEGER PRIMARY KEY,source_file TEXT NOT NULL,source_sheet TEXT NOT NULL,source_row INTEGER NOT NULL,raw_json TEXT NOT NULL,entity_type TEXT,status TEXT NOT NULL,review_reason TEXT);
CREATE TABLE reconciliation(id INTEGER PRIMARY KEY,created_at TEXT NOT NULL,entity_type TEXT NOT NULL,source_value NUMERIC,erp_value NUMERIC,difference NUMERIC,notes TEXT);
